package com.campus.lostfound;
import jakarta.persistence.*; import java.time.*;
@Entity public class Report {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;
 private String type,title,category,location,reporterName,reporterEmail,reporterPhone,status="OPEN"; @Column(length=1200) private String description; @Column(length=100_000_000) private String imageData; private LocalDate itemDate; private LocalDateTime createdAt=LocalDateTime.now();
 public Report(){} public Long getId(){return id;} public void setId(Long v){id=v;} public String getType(){return type;} public void setType(String v){type=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getLocation(){return location;} public void setLocation(String v){location=v;} public String getReporterName(){return reporterName;} public void setReporterName(String v){reporterName=v;} public String getReporterEmail(){return reporterEmail;} public void setReporterEmail(String v){reporterEmail=v;} public String getReporterPhone(){return reporterPhone;} public void setReporterPhone(String v){reporterPhone=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getImageData(){return imageData;} public void setImageData(String v){imageData=v;} public LocalDate getItemDate(){return itemDate;} public void setItemDate(LocalDate v){itemDate=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;}
}
